import sys

def valid(s):
    n = len(s)
    i = 0
    if i < n and s[i] in '+-':
        i += 1
    d1 = 0
    while i < n and '0' <= s[i] <= '9':
        i += 1
        d1 += 1
    d2 = 0
    if i < n and s[i] == '.':
        i += 1
        while i < n and '0' <= s[i] <= '9':
            i += 1
            d2 += 1
    if d1 + d2 == 0:
        return False
    if i < n and s[i] in 'eE':
        i += 1
        if i < n and s[i] in '+-':
            i += 1
        d3 = 0
        while i < n and '0' <= s[i] <= '9':
            i += 1
            d3 += 1
        if d3 == 0:
            return False
    return i == n

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    print('\n'.join('true' if valid(s) else 'false' for s in data[1:1 + t]))

main()

