def gen(rng):
    import itertools
    def fmt(strs):
        return str(len(strs)) + '\n' + '\n'.join(strs)
    def digits(lo, hi):
        return ''.join(rng.choice('0123456789') for _ in range(rng.randint(lo, hi)))
    def valid_str():
        s = rng.choice(['', '', '+', '-'])
        k = rng.randint(0, 3)
        if k == 0:
            s += digits(1, 5)
        elif k == 1:
            s += digits(1, 4) + '.'
        elif k == 2:
            s += digits(1, 3) + '.' + digits(1, 3)
        else:
            s += '.' + digits(1, 4)
        if rng.random() < 0.4:
            s += rng.choice('eE') + rng.choice(['', '+', '-']) + digits(1, 3)
        return s
    def mutate(s):
        alpha = '0123456789+-.eE'
        r = rng.random()
        pos = rng.randint(0, len(s))
        if r < 0.35 and len(s) > 1:
            pos = rng.randrange(len(s))
            return s[:pos] + s[pos + 1:]
        if r < 0.7:
            return s[:pos] + rng.choice(alpha) + s[pos:]
        if len(s) == 0:
            return rng.choice(alpha)
        pos = rng.randrange(len(s))
        return s[:pos] + rng.choice(alpha) + s[pos + 1:]
    def mixed(cnt, maxlen):
        out = []
        while len(out) < cnt:
            s = valid_str()
            if rng.random() < 0.55:
                s = mutate(s)
                if rng.random() < 0.3:
                    s = mutate(s)
            if 1 <= len(s) <= maxlen:
                out.append(s)
        return out
    tests = [
        fmt(['3.14', '+.8', '.', '1e', '-7e-2', '1.2.3']),
        fmt(['5.', '.e1', '0e0', '+-3']),
        fmt(['9E5', '12e3.5', '+']),
        fmt(['0']), fmt(['.']), fmt(['e']), fmt(['+.']), fmt(['6e-1']), fmt(['-.5E+5']), fmt(['1e1e1']), fmt(['1.e5', '.1e', 'e.1']),
    ]
    for _ in range(10):
        tests.append(fmt(mixed(rng.randint(3, 12), 20)))
    al = '0.e+-'
    allstr = []
    for L in range(1, 5):
        allstr += [''.join(p) for p in itertools.product(al, repeat=L)]
    tests.append(fmt(allstr))
    al2 = '01.eE+-'
    allstr = []
    for L in range(1, 4):
        allstr += [''.join(p) for p in itertools.product(al2, repeat=L)]
    tests.append(fmt(allstr))
    tests.append(fmt(mixed(5000, 20)))
    tests.append(fmt(mixed(5000, 20)))
    tests.append(fmt([valid_str() if rng.random() < 0.5 else mutate(valid_str()) for _ in range(5000)][:5000]))
    big = []
    while len(big) < 5000:
        s = ''.join(rng.choice('0123456789') for _ in range(rng.randint(10, 20)))
        k = rng.random()
        if k < 0.3:
            p = rng.randrange(len(s))
            s = s[:p] + '.' + s[p + 1:]
        elif k < 0.6:
            p = rng.randrange(1, len(s) - 3)
            s = s[:p] + 'e' + rng.choice(['', '+', '-']) + s[p + 2:]
        s = s[:20]
        big.append(s)
    tests.append(fmt(big))
    return tests

